<script>let current='Semua';function openModal(){document.getElementById('modal').classList.add('show')}function closeModal(){document.getElementById('modal').classList.remove('show')}document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});function setFilter(cat,el){current=cat;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');filterProjects()}function filterProjects(){const q=(document.getElementById('search').value||'').toLowerCase();document.querySelectorAll('.project').forEach(p=>{const okCat=current==='Semua'||p.dataset.cat===current;const okQ=!q||p.dataset.search.includes(q);p.classList.toggle('hide',!(okCat&&okQ))})}function detail(i){const p=<?php echo json_encode($projects,JSON_UNESCAPED_SLASHES);?>[i];openModal(p[1])}</script></body></html>